solutionCodeJson.code:
// Bài 10.1 — duyệt một lượt, nhớ (ký tự, số lần); ghi ra khi ký tự đổi VÀ ở cuối chuỗi
function compress(s) {
  if (/\d/.test(s)) throw new TypeError('digits are not allowed');
  let out = '';
  for (let i = 0; i < s.length; ) {
    let j = i;
    while (j < s.length && s[j] === s[i]) j++;
    out += s[i] + (j - i > 1 ? String(j - i) : '');
    i = j;
  }
  return out;
}

function expand(s) {
  return s.replace(/([a-zA-Z])(\d*)/g, (_, ch, n) => ch.repeat(n ? Number(n) : 1));
}

